<?php
use EIPSI\StudyEngine\Builder as B;use EIPSI\StudyEngine\Persistence as P;use EIPSI\StudyEngine\Contracts\Canonical;use EIPSI\StudyEngine\Longitudinal as L;use EIPSI\StudyEngine\Privacy as G;
function pi_api($op,$args=array()){return B\Admin::handle(array_merge(array('operation'=>$op),$args),wp_create_nonce('eipsi_study_builder'));}
function pi_save($e,$d){return pi_api('save',array('id'=>$e['id'],'revision'=>$e['revision'],'request_id'=>'PI_SAVE_'.bin2hex(random_bytes(8)),'definition'=>$d));}
function pi_add($e,$id,$parent='M_ROOT',$position=0,$scope='MICRO'){$d=$e['definition'];$d['nodes'][]=B\Draft::block($id,$d['id'],$parent,$scope,$position);return pi_save($e,$d);}
function pi_import($e,$id,$blocks){$post=wp_insert_post(array('post_type'=>'eipsi_form_template','post_status'=>'draft','post_title'=>'P1-I synthetic','post_content'=>serialize_blocks(array(pe_block('eipsi/form-container',array('allowBackwardsNav'=>true),$blocks)))));pe_assert($post>0,'Source create');$GLOBALS['pi_posts'][]=$post;return pi_api('import',array('id'=>$e['id'],'revision'=>$e['revision'],'request_id'=>'PI_IMPORT_'.bin2hex(random_bytes(8)),'assessment'=>$id,'template'=>$post));}
function pi_question($e,$key){foreach($e['definition']['nodes'] as $n)if($n['kind']==='QUESTION'&&substr($n['response_key'],-strlen('_'.$key))==='_'.$key)return $n;throw new RuntimeException('Question missing '.$key);}
function pi_edit($e,$id,$mutator){$d=$e['definition'];foreach($d['nodes'] as &$n)if($n['id']===$id)$n=$mutator($n);unset($n);return pi_save($e,$d);}
function pi_ready($name,$long=true){$e=pi_api('create',array('administration'=>array('name'=>'Pilot '.$name,'contact'=>'Internal synthetic','public_id'=>'PILOT_'.strtoupper($name).'_'.bin2hex(random_bytes(5))),'request_id'=>'PI_CREATE_'.bin2hex(random_bytes(8))));if($long){$d=L\Configuration::apply($e['definition'],array('verification_policy'=>'ALLOW_UNVERIFIED','reminder_offsets'=>array(15,30),'immediate_availability_policy'=>'SEND'));$e=pi_save($e,$d);}return $e;}
function pi_release($e){$v=pi_api('validate',array('id'=>$e['id']));$errors=array_filter($v['issues'],static function($i){return $i['severity']==='ERROR';});pe_assert(!$errors,'Publish diagnostics '.Canonical::json($errors));$preview=pi_api('simulate',array('id'=>$e['id'],'context'=>array('created_at'=>$GLOBALS['pf_now'],'timezone'=>'UTC','seed_hex'=>str_repeat('01',32)),'commands'=>array()));$acks=array_values(array_map(static function($i){return $i['code'].'|'.($i['node_id']??$i['path']??'');},$v['issues']));$e=pi_api('publish',array('id'=>$e['id'],'revision'=>$e['revision'],'acknowledgements'=>$acks));$e=pi_api('activate',array('id'=>$e['id'],'revision'=>$e['revision'],'state'=>'OPEN'));$e['preview']=$preview;return $e;}
function pi_p($e){return array('public'=>$e['definition']['study']['public_id'],'version'=>$e['id'],'definition'=>$e['definition']);}
function pi_frame($e,$email=null){if($e['definition']['protocol_metadata']['enrollment_mode']==='ANONYMOUS')return pe_runtime()->handle(pi_p($e)['public']);$f=pf_enroll(pi_p($e),$email);return pf_runtime()->redeem(pi_p($e)['public'],pf_mint($f,'VERIFY_PARTICIPANT'));}
function pi_reload($f){return !empty($f['longitudinal'])?pf_runtime()->handle($f['study']['public_id'],$f['token']):pe_runtime()->handle($f['study']['public_id'],$f['token']);}
function pi_act($f,$action,$answers=array()){return !empty($f['longitudinal'])?pf_runtime()->handle($f['study']['public_id'],$f['token'],pe_request($f,$action,$answers)):pe_runtime()->handle($f['study']['public_id'],$f['token'],pe_request($f,$action,$answers));}
function pi_answers($f,$overrides=array()){$out=array();$p=$f['view']['presentation'];$page=$p['pages'][$p['page_cursor']];foreach($f['definition']['nodes'] as $n)if($n['kind']==='QUESTION'&&in_array($n['id'],$page,true)&&!isset($f['view']['snapshot']['coverage'][$f['view']['next_action']['payload']['assessment_execution_id']][$n['id']]))$out[$n['response_key']]=$overrides[$n['response_key']]??($n['type']==='BOOLEAN'?'true':($n['type']==='CHOICE'?$n['options'][0]['id']:($n['type']==='TEXT'?'Synthetic response':'3')));return $out;}
function pi_finish($f){for($i=0;$i<100;$i++){if($f['view']['next_action']['kind']==='EMAIL_CONFIRMATION_REQUIRED'){pe_assert(!$f['email_confirmation']['requires_link'],'Pilot NEVER review unexpectedly requires link');$f=pf_runtime()->handle($f['study']['public_id'],$f['token'],array('action'=>'confirm_email','command_id'=>'PI_EMAIL_REVIEW_'.bin2hex(random_bytes(8)),'csrf'=>$f['csrf'],'expected_revision'=>$f['view']['revision'],'email'=>pf_participant($f)['email']));continue;}if($f['view']['next_action']['kind']!=='OPEN_ASSESSMENT')return $f;$p=$f['view']['presentation'];$action=$p['page_cursor']<count($p['pages'])-1?'next':'submit';$f=pi_act($f,$action,pi_answers($f));}throw new RuntimeException('Pilot traversal cap');}
function pi_export($e,$f,$name){global $pilot;$data=(new G\ExportAdapter(pf_db()))->dataset($e['study_id']);pe_assert(count($data['rows'])>0,'Export empty');$vid=$f['version_id'];pe_assert(isset($data['manifest'][$vid]),'Manifest version');$stored=(new P\StudyVersionRepository(pf_db()))->find($vid);pe_assert($data['manifest'][$vid]['protocol_hash']===$stored['protocol_hash'],'Export protocol mismatch');$pilot[$name]=array('study_id'=>$e['study_id'],'version'=>$vid,'execution'=>$f['access']['execution_id'],'state'=>$f['view']['next_action']['kind'],'rows'=>count($data['rows']),'occurrences'=>count(array_filter($f['view']['snapshot']['instances'],static function($b)use($e){foreach($e['definition']['nodes'] as $n)if($n['id']===$b['definition_id'])return ($n['completion_boundary']??null)==='ASSESSMENT';return false;})),'random_decisions'=>count($f['view']['snapshot']['random_decisions']),'protocol_hash'=>$stored['protocol_hash']);return $data;}
function pi_simple($name,$long=true){$e=pi_ready($name,$long);$e=pi_add($e,'E_ONE');$e=pi_import($e,'E_ONE',array(pe_question('answer')));return $e;}
